package com.xdownload.mobile;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.widget.*;
import androidx.media3.common.MediaItem;
import androidx.media3.transformer.*;
import java.io.*;
import java.util.concurrent.*;
public class ExportActivity extends Activity {
 private Transformer transformer;private Uri source;private File temp;private TextView status;private Button trim,extract,save;private boolean busy=false,ready=false;private boolean copying=false;private volatile boolean dead=false;private boolean audio=false,mp3=false;private Button mp3Button,full,compress,merge,mergeAudio,trimAudio;private boolean clipAudio=false;private boolean mergeSound=false;private boolean fullVideo=false,resize=false;
 private final ExecutorService io=Executors.newSingleThreadExecutor();
 private EditText start,end;
 @Override public void onCreate(Bundle b){super.onCreate(b);purgeOldFiles();source=getIntent().getData();LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(24,24,24,24);l.setBackgroundColor(0xff121923);
 TextView title=new TextView(this);title.setText("Export media • MP4 / M4A");title.setTextSize(22);l.addView(title);
 start=new EditText(this);start.setInputType(8194);start.setHint("Start time (seconds)");start.setText("0");l.addView(start);
 end=new EditText(this);end.setInputType(8194);end.setHint("End time (seconds)");l.addView(end);
 trim=new Button(this);trim.setText("Trim video to MP4");trim.setOnClickListener(v->{fullVideo=false;resize=false;begin(false);});l.addView(trim);full=new Button(this);full.setText("Convert full video to MP4 (H.264/AAC)");full.setOnClickListener(v->{fullVideo=true;resize=false;begin(false);});l.addView(full);compress=new Button(this);compress.setText("Resize / convert to 720p MP4");compress.setOnClickListener(v->{fullVideo=true;resize=true;begin(false);});l.addView(compress);
 extract=new Button(this);extract.setText("Extract AAC audio to M4A");extract.setOnClickListener(v->{clipAudio=false;fullVideo=false;resize=false;begin(true);});l.addView(extract);trimAudio=new Button(this);trimAudio.setText("Trim audio to M4A");trimAudio.setOnClickListener(v->{clipAudio=true;fullVideo=false;resize=false;begin(true);});l.addView(trimAudio);
 mp3Button=new Button(this);mp3Button.setText("Extract MP3 audio");mp3Button.setOnClickListener(v->beginMp3());l.addView(mp3Button);merge=new Button(this);merge.setText("Merge selected videos (MP4)");merge.setOnClickListener(v->pickMerge(false));l.addView(merge);mergeAudio=new Button(this);mergeAudio.setText("Merge selected audio files (M4A)");mergeAudio.setOnClickListener(v->pickMerge(true));l.addView(mergeAudio);
 status=new TextView(this);status.setText("Keep this screen open during export. The original file is not changed.");l.addView(status);
 save=new Button(this);save.setText("Save exported file");save.setEnabled(false);save.setOnClickListener(v->pick());l.addView(save);ScrollView scroll=new ScrollView(this);scroll.addView(l);setContentView(scroll);}
 private void pickMerge(boolean sound){if(busy||source==null)return;mergeSound=sound;startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(sound?"audio/*":"video/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true),81);}
 static Composition mergeComposition(Uri first,Uri second,boolean sound){return mergeComposition(first,java.util.Collections.singletonList(second),sound);}
 static Composition mergeComposition(Uri first,java.util.List<Uri> more,boolean sound){EditedMediaItem[] items=new EditedMediaItem[more.size()+1];items[0]=new EditedMediaItem.Builder(MediaItem.fromUri(first)).setRemoveVideo(sound).build();for(int i=0;i<more.size();i++)items[i+1]=new EditedMediaItem.Builder(MediaItem.fromUri(more.get(i))).setRemoveVideo(sound).build();return new Composition.Builder(new EditedMediaItemSequence.Builder(items).build()).build();}
 private void beginMerge(java.util.List<Uri> second){if(busy||source==null)return;try{if(temp!=null)temp.delete();temp=File.createTempFile("xdownload-export-",".mp4",getCacheDir());if(!temp.delete())throw new IOException("Cannot prepare output");mp3=false;audio=mergeSound;ready=false;busy=true;trim.setEnabled(false);trimAudio.setEnabled(false);full.setEnabled(false);compress.setEnabled(false);merge.setEnabled(false);mergeAudio.setEnabled(false);extract.setEnabled(false);mp3Button.setEnabled(false);save.setEnabled(false);status.setText("Merging media…");transformer=new Transformer.Builder(this).setVideoMimeType(androidx.media3.common.MimeTypes.VIDEO_H264).setAudioMimeType(androidx.media3.common.MimeTypes.AUDIO_AAC).addListener(new Transformer.Listener(){@Override public void onCompleted(Composition c,ExportResult r){busy=false;ready=true;trim.setEnabled(true);trimAudio.setEnabled(true);full.setEnabled(true);compress.setEnabled(true);merge.setEnabled(true);mergeAudio.setEnabled(true);extract.setEnabled(true);mp3Button.setEnabled(true);save.setEnabled(true);status.setText("Merge complete. Choose where to save.");}@Override public void onError(Composition c,ExportResult r,ExportException x){error(x.getMessage());}}).build();transformer.start(mergeComposition(source,second,audio),temp.getAbsolutePath());}catch(Exception x){error(x.getMessage());}}
 private void purgeOldFiles(){File[] files=getCacheDir().listFiles();if(files!=null)for(File file:files){String n=file.getName();if((n.startsWith("xdownload-export-")||n.startsWith("xdownload-input-")||n.startsWith("xdownload-mp3-"))&&System.currentTimeMillis()-file.lastModified()>86400000L)file.delete();}}
 private void begin(boolean sound){if(source==null||busy)return;mp3=false;long a=0,b=0;try{if((!sound||clipAudio)&&!fullVideo){a=(long)(Double.parseDouble(start.getText().toString())*1000);b=(long)(Double.parseDouble(end.getText().toString())*1000);if(a<0||b<=a)throw new IllegalArgumentException();}}catch(Exception e){status.setText("Enter valid start and end times.");return;}
 try{if(temp!=null)temp.delete();temp=File.createTempFile("xdownload-export-",".mp4",getCacheDir());if(!temp.delete())throw new IOException("Cannot prepare output");audio=sound;ready=false;busy=true;trim.setEnabled(false);trimAudio.setEnabled(false);full.setEnabled(false);compress.setEnabled(false);merge.setEnabled(false);mergeAudio.setEnabled(false);extract.setEnabled(false);mp3Button.setEnabled(false);save.setEnabled(false);status.setText("Exporting…");
 MediaItem.Builder m=new MediaItem.Builder().setUri(source);if((!sound||clipAudio)&&!fullVideo)m.setClippingConfiguration(new MediaItem.ClippingConfiguration.Builder().setStartPositionMs(a).setEndPositionMs(b).build());
 EditedMediaItem.Builder itemBuilder=new EditedMediaItem.Builder(m.build()).setRemoveVideo(sound);if(resize&&!sound)itemBuilder.setEffects(new Effects(java.util.Collections.emptyList(),java.util.Collections.singletonList(androidx.media3.effect.Presentation.createForHeight(720))));EditedMediaItem item=itemBuilder.build();
 transformer=new Transformer.Builder(this).setVideoMimeType(androidx.media3.common.MimeTypes.VIDEO_H264).setAudioMimeType(androidx.media3.common.MimeTypes.AUDIO_AAC).addListener(new Transformer.Listener(){@Override public void onCompleted(Composition c,ExportResult r){busy=false;ready=true;trim.setEnabled(true);trimAudio.setEnabled(true);full.setEnabled(true);compress.setEnabled(true);merge.setEnabled(true);mergeAudio.setEnabled(true);extract.setEnabled(true);mp3Button.setEnabled(true);save.setEnabled(true);status.setText("Export ready. Choose where to save.");}@Override public void onError(Composition c,ExportResult r,ExportException e){error(e.getMessage());}}).build();
 transformer.start(item,temp.getAbsolutePath());
 }catch(Exception e){error(e.getMessage());}}
  private void beginMp3(){if(source==null||busy)return;mp3=true;audio=true;ready=false;busy=true;trim.setEnabled(false);trimAudio.setEnabled(false);extract.setEnabled(false);mp3Button.setEnabled(false);save.setEnabled(false);full.setEnabled(false);compress.setEnabled(false);merge.setEnabled(false);mergeAudio.setEnabled(false);status.setText("Encoding MP3…");io.execute(()->{File input=null,output=null;try{input=File.createTempFile("xdownload-input-",".media",getCacheDir());output=File.createTempFile("xdownload-mp3-",".mp3",getCacheDir());try(InputStream in=getContentResolver().openInputStream(source);OutputStream out=new FileOutputStream(input)){if(in==null)throw new IOException("Cannot read media");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){if(dead)throw new IOException("Cancelled");out.write(b,0,n);}}encodeMp3(input,output);if(dead){output.delete();return;}final File result=output;runOnUiThread(()->{if(dead){result.delete();return;}if(temp!=null)temp.delete();temp=result;busy=false;ready=true;trim.setEnabled(true);trimAudio.setEnabled(true);extract.setEnabled(true);mp3Button.setEnabled(true);save.setEnabled(true);full.setEnabled(true);compress.setEnabled(true);merge.setEnabled(true);mergeAudio.setEnabled(true);status.setText("MP3 ready — choose where to save");});}catch(Exception|LinkageError e){if(output!=null)output.delete();runOnUiThread(()->{if(!dead)error("MP3: "+e.getMessage());});}finally{if(input!=null)input.delete();}});}
 static void encodeMp3(File input,File output)throws IOException{com.arthenica.ffmpegkit.FFmpegSession s=com.arthenica.ffmpegkit.FFmpegKit.executeWithArguments(new String[]{"-y","-i",input.getAbsolutePath(),"-vn","-map","0:a:0","-c:a","libmp3lame","-q:a","3",output.getAbsolutePath()});if(!com.arthenica.ffmpegkit.ReturnCode.isSuccess(s.getReturnCode())||output.length()<100)throw new IOException("MP3 encoder did not produce a valid output");}
 private void error(String s){busy=false;ready=false;trim.setEnabled(true);trimAudio.setEnabled(true);full.setEnabled(true);compress.setEnabled(true);merge.setEnabled(true);mergeAudio.setEnabled(true);extract.setEnabled(true);mp3Button.setEnabled(true);save.setEnabled(false);status.setText("Export failed: "+s);}
 private void pick(){if(!ready)return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mp3?"audio/mpeg":audio?"audio/mp4":"video/mp4").putExtra(Intent.EXTRA_TITLE,mp3?"XDownload-audio.mp3":audio?"XDownload-audio.m4a":"XDownload-trim.mp4");startActivityForResult(i,27);}
 @Override protected void onActivityResult(int req,int result,Intent i){super.onActivityResult(req,result,i);if(req==81&&result==RESULT_OK&&i!=null){java.util.ArrayList<Uri> files=new java.util.ArrayList<>();if(i.getClipData()!=null){if(i.getClipData().getItemCount()>9){status.setText("Choose at most nine additional files.");return;}for(int n=0;n<i.getClipData().getItemCount();n++){Uri u=i.getClipData().getItemAt(n).getUri();if(u!=null)files.add(u);}}else if(i.getData()!=null)files.add(i.getData());if(!files.isEmpty())beginMerge(files);return;}if(req==27&&result==RESULT_OK&&i!=null&&i.getData()!=null&&ready){Uri dest=i.getData();File input=temp;copying=true;save.setEnabled(false);trim.setEnabled(false);trimAudio.setEnabled(false);extract.setEnabled(false);busy=true;io.execute(()->{try(InputStream in=new FileInputStream(input);OutputStream out=getContentResolver().openOutputStream(dest,"w")){if(out==null)throw new IOException("Cannot open output");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);runOnUiThread(()->{if(!dead){status.setText("Saved");copying=false;busy=false;save.setEnabled(true);trim.setEnabled(true);trimAudio.setEnabled(true);extract.setEnabled(true);mp3Button.setEnabled(true);}});}catch(Exception e){runOnUiThread(()->{if(!dead){copying=false;error(e.getMessage());}});}finally{if(dead)input.delete();}});}}
 @Override protected void onDestroy(){dead=true;if(transformer!=null&&busy)transformer.cancel();io.shutdown();if(temp!=null&&!copying)temp.delete();super.onDestroy();}
}
